import{_ as a}from"./chunks/library-overview.Bu864uIA.js";import{_ as t,o,c as s,a2 as r}from"./chunks/framework.Dx-TCpNt.js";const m=JSON.parse('{"title":"Library & Import","description":"The library is built by scanning the raw/ folder each time the app loads. There is no database and no import step that copies your images: the directory…","frontmatter":{"description":"The library is built by scanning the raw/ folder each time the app loads. There is no database and no import step that copies your images: the directory…"},"headers":[],"relativePath":"guide/gallery.md","filePath":"guide/gallery.md","lastUpdated":1794727111000}'),n={name:"guide/gallery.md"};function i(d,e,l,h,c,p){return o(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="library-import" tabindex="-1">Library &amp; Import <a class="header-anchor" href="#library-import" aria-label="Permalink to &quot;Library &amp; Import&quot;">​</a></h1><p>The library is built by scanning the <code>raw/</code> folder each time the app loads. There is no database and no import step that copies your images: <strong>the directory structure is the configuration</strong>.</p><p>This page covers how to lay out files, how the scanner pairs languages, how to add a folder that lives somewhere else, and which import dialogs exist.</p><h2 id="the-problem-it-solves" tabindex="-1">The problem it solves <a class="header-anchor" href="#the-problem-it-solves" aria-label="Permalink to &quot;The problem it solves&quot;">​</a></h2><p>Manga scans arrive in arbitrary folder shapes: <code>Vol.14/Japanese/ch01</code>, <code>点兔第14卷/ja/172</code>, <code>manga/zh-cn/172</code>. You want one shelf that lists volumes and chapters, pairs page 1 of every language with page 1 of every other language, and tells you where a file is missing — without renaming or moving anything.</p><h2 id="directory-shape" tabindex="-1">Directory shape <a class="header-anchor" href="#directory-shape" aria-label="Permalink to &quot;Directory shape&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>raw/</span></span>
<span class="line"><span>  &lt;volume&gt;/</span></span>
<span class="line"><span>    &lt;language-dir&gt;/</span></span>
<span class="line"><span>      &lt;chapter&gt;/</span></span>
<span class="line"><span>        001.jpg</span></span>
<span class="line"><span>        002.jpg</span></span></code></pre></div><ul><li>A <strong>volume</strong> is any top-level folder under <code>raw/</code>.</li><li>A <strong>chapter</strong> is any folder inside a language directory. Chapters are unioned across languages, so one language may be missing a chapter folder.</li><li><strong>Pages are paired by sorted position, not by filename.</strong> Each language&#39;s files are sorted with a natural sort (digit runs compared numerically), then paired by index. <code>1.jpg</code>, <code>2.jpg</code>, <code>10.jpg</code> sorts correctly.</li></ul><figure class="shot"><img src="`+a+`" alt="Library sidebar with volumes, chapters and language badges"><figcaption>The sidebar lists volume → chapter → pages. Language badges show which languages exist for a volume; warnings appear inline.</figcaption></figure><h2 id="language-directory-names" tabindex="-1">Language directory names <a class="header-anchor" href="#language-directory-names" aria-label="Permalink to &quot;Language directory names&quot;">​</a></h2><p>The scanner normalizes a folder name (lowercase, spaces and underscores to hyphens) and matches it against aliases:</p><table tabindex="0"><thead><tr><th>Language</th><th>Accepted directory names</th></tr></thead><tbody><tr><td>Japanese (<code>ja</code>)</td><td><code>ja</code>, <code>jp</code>, <code>jpn</code>, <code>japanese</code>, <code>ja-jp</code>, <code>日</code>, <code>日本語</code>, <code>日文</code></td></tr><tr><td>Chinese (<code>zh</code>)</td><td><code>zh</code>, <code>zh-cn</code>, <code>zh-hans</code>, <code>zh-sg</code>, <code>cn</code>, <code>chs</code>, <code>zh-tw</code>, <code>zh-hk</code>, <code>zh-hant</code>, <code>cht</code>, <code>tw</code>, <code>hk</code>, <code>中</code>, <code>中文</code>, <code>繁中</code>, <code>简中</code></td></tr><tr><td>English (<code>en</code>)</td><td><code>en</code>, <code>en-us</code>, <code>en-gb</code>, <code>us</code>, <code>uk</code>, <code>eng</code>, <code>english</code>, <code>英</code>, <code>英文</code></td></tr></tbody></table><p>If a folder name is not recognized, the volume still appears but with a warning. Open <strong>volume settings</strong> (the gear on the volume row) to pin a directory to a language. The choice is stored in <code>data/library.json</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;volumes&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;点兔第14卷&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;dirs&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;ja&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;raw-ja&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;zh&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;raw-zh&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>A volume may have one, two or three languages. The compare reader only offers languages that actually exist for the current page.</p><h2 id="adding-a-folder-that-lives-elsewhere" tabindex="-1">Adding a folder that lives elsewhere <a class="header-anchor" href="#adding-a-folder-that-lives-elsewhere" aria-label="Permalink to &quot;Adding a folder that lives elsewhere&quot;">​</a></h2><p><strong>＋ Add manga</strong> has two modes:</p><table tabindex="0"><thead><tr><th>Mode</th><th>What happens</th></tr></thead><tbody><tr><td>Leave the path blank</td><td>Creates an empty folder under <code>raw/</code>.</td></tr><tr><td>Pick an existing folder</td><td>Creates a <strong>folder link</strong> under <code>raw/</code> that points at the original. Images are not copied, and annotations remain writable because the link behaves like a normal folder.</td></tr></tbody></table><p>Optional: give the volume a different display name. The hint under the field repeats the expected layout: <code>language/chapter/page.jpg</code>.</p><p><strong>Remove from library</strong> (in volume settings) deletes only the link under <code>raw/</code>; images in the original folder are untouched, and annotations already saved under <code>data/pages/</code> are kept.</p><p>In a plain browser the folder picker is not available. Type the absolute path instead, or use the desktop build and click <strong>Choose a folder…</strong>.</p><h2 id="page-and-language-roles" tabindex="-1">Page and language roles <a class="header-anchor" href="#page-and-language-roles" aria-label="Permalink to &quot;Page and language roles&quot;">​</a></h2><p>Three different &quot;roles&quot; are easy to confuse:</p><table tabindex="0"><thead><tr><th>Role</th><th>Where it is chosen</th><th>What it affects</th></tr></thead><tbody><tr><td><strong>Base image</strong></td><td>Panel workbench toolbar</td><td>Which language&#39;s artwork you draw panels on. Panel rectangles are shared by all languages on that page.</td></tr><tr><td><strong>Compare languages</strong></td><td>Compare reader language chips</td><td>Which languages are displayed, in which order. Not every language has to be enabled.</td></tr><tr><td><strong>Primary language</strong></td><td>PNG export</td><td>Whole-page and current-panel PNG use the base language; the trilingual collage uses the selected compare languages.</td></tr></tbody></table><p>Panels and notes are stored once per page, not once per language. Alignment offsets are stored per language and, optionally, per panel.</p><h2 id="warnings-you-will-see" tabindex="-1">Warnings you will see <a class="header-anchor" href="#warnings-you-will-see" aria-label="Permalink to &quot;Warnings you will see&quot;">​</a></h2><p>Library warnings are informational; the page still opens.</p><table tabindex="0"><thead><tr><th>Warning</th><th>Meaning</th><th>Fix</th></tr></thead><tbody><tr><td><em>No language directory recognized</em></td><td>None of the subfolders matched an alias.</td><td>Map them in volume settings or rename them.</td></tr><tr><td><em>Unrecognized directory: …</em></td><td>Extra folders sit next to language folders.</td><td>Map them, or ignore them.</td></tr><tr><td><em>Page counts differ across languages</em></td><td>Languages have different numbers of files.</td><td>Pairing is by index; add or remove the missing page.</td></tr><tr><td><em>Mixed extensions in this chapter</em></td><td>e.g. <code>.jpg</code> and <code>.png</code> alternate.</td><td>Usually harmless; normalize if you care about consistent thumbnails.</td></tr><tr><td><em>Filename does not match page number</em></td><td>The leading number in the filename differs from its sorted position.</td><td>Rename if the mismatch indicates a missing or extra page.</td></tr></tbody></table><h2 id="folder-detection-rules" tabindex="-1">Folder detection rules <a class="header-anchor" href="#folder-detection-rules" aria-label="Permalink to &quot;Folder detection rules&quot;">​</a></h2><p><strong>Folder rules…</strong> (sidebar) lets you describe page paths with placeholders instead of relying on the fixed <code>volume/language/chapter</code> shape:</p><ul><li>Placeholders: <code>series</code>, <code>volume</code>, <code>chapter</code>, <code>language</code>, <code>page</code>.</li><li><code>*</code> matches any single segment; <code>**</code> matches an optional segment.</li><li>Rules are tried in order and the first match wins.</li><li>The dialog includes a live preview: how many files and volumes matched, which files were not recognized, and which pages each chapter contains.</li><li><strong>Fill in the default rules</strong> restores the built-in shape; <strong>Restore defaults</strong> discards your edits.</li><li><strong>Save rules</strong> rescans the library with the new rules.</li></ul><p>Rules only affect detection. They never rename or move files.</p><h2 id="import-exchange-and-restore" tabindex="-1">Import, exchange and restore <a class="header-anchor" href="#import-exchange-and-restore" aria-label="Permalink to &quot;Import, exchange and restore&quot;">​</a></h2><p>Four different entry points live in the sidebar. They do different things:</p><table tabindex="0"><thead><tr><th>Entry</th><th>Use it for</th></tr></thead><tbody><tr><td><strong>Add manga</strong></td><td>Link an existing image folder into the library.</td></tr><tr><td><strong>Project file…</strong></td><td>Export or import a <code>.mnproj</code> package (images + annotations + templates + language settings).</td></tr><tr><td><strong>Exchange files…</strong></td><td>Move <code>.mntpl</code> layout templates, <code>.mnexp</code> export templates or a single <code>.mnpage.json</code> page.</td></tr><tr><td><strong>Backup / restore</strong></td><td>ZIP the <code>data/</code> folder, or restore a previous ZIP.</td></tr></tbody></table><p>Imports are validated first and the original files are backed up under <code>data/backups/</code>. See <a href="/KomaYomi-docs/guide/project-files">Project Files &amp; Formats</a> for the file contents and version rules.</p><div class="tip custom-block"><p class="custom-block-title">Import order</p><p>Restore a <strong>backup</strong> when you want your annotations back on the same machine. Import a <strong>project</strong> when you move to another machine. Use <strong>exchange files</strong> when you only want to share a layout, an export style or one page.</p></div><h2 id="navigation-and-performance" tabindex="-1">Navigation and performance <a class="header-anchor" href="#navigation-and-performance" aria-label="Permalink to &quot;Navigation and performance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Shortcut</th></tr></thead><tbody><tr><td>Previous / next page</td><td><code>[</code> / <code>]</code></td></tr><tr><td>Panel workbench</td><td><code>P</code></td></tr><tr><td>Compare reader</td><td><code>C</code></td></tr><tr><td>Toggle sidebar</td><td><code>S</code></td></tr><tr><td>Toggle notes panel</td><td><code>N</code></td></tr><tr><td>Open export dialog</td><td><code>E</code></td></tr><tr><td>Help</td><td><code>?</code></td></tr></tbody></table><p>The URL hash is deep-linkable: <code>#/&lt;volume&gt;/&lt;chapter&gt;/&lt;page&gt;/&lt;panels|compare&gt;</code>.</p><p>Thumbnails are generated on demand and cached in <code>data/cache/thumbs/</code>. Deleting that folder is safe; thumbnails are rebuilt on the next visit. The image format is sniffed from the file header, so a <code>.png</code> that is really a JPEG still renders correctly.</p><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common pitfalls&quot;">​</a></h2><ul><li><strong>Renaming a file changes its page position.</strong> Pairing is by sorted index; inserting a page shifts every page after it. Add the new page at the end, or rename the whole chapter consistently.</li><li><strong>One missing language is not an error.</strong> The page opens, and the compare reader shows a placeholder for the missing language.</li><li><strong>A folder link is not a copy.</strong> If you move or delete the original folder, the library breaks. Re-add the folder after moving it.</li><li><strong>WebP is displayed but not decoded for detection.</strong> Use JPEG or PNG when you rely on automatic splitting (see <a href="/KomaYomi-docs/guide/panels">Panel Workbench</a>).</li><li><strong>The sidebar is the truth.</strong> If a volume or chapter is missing, check the folder name casing and the language aliases before anything else.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/KomaYomi-docs/guide/panels">Panel Workbench</a> — what to do after a page opens.</li><li><a href="/KomaYomi-docs/guide/project-files">Project Files &amp; Formats</a> — what a <code>.mnproj</code> contains.</li><li><a href="/KomaYomi-docs/guide/remote">Remote Storage &amp; Backup</a> — keeping images on a NAS or WebDAV.</li></ul>`,45)])])}const b=t(n,[["render",i]]);export{m as __pageData,b as default};
